import { Component, inject } from '@angular/core';
import { TenantLoginProvider } from 'app/features/identity/tenant-login-provider/model/tenant-login-provider.model';
import { TenantLoginProviderRepository } from 'app/features/identity/tenant-login-provider/repository/tenant-login-provider-repository.service';
import { ConfirmSelectionAction } from 'app/shared/toolkit/action/confirm-selection-action';

@Component({ selector: 'tenant-login-provider-view-disable-selection-action', standalone: false, template: '' })
export class TenantLoginProviderViewDisableSelectionActionComponent extends ConfirmSelectionAction<TenantLoginProvider> {
  readonly name = 'disableSelection';
  protected readonly scope = 'identity/tenant-login-provider';
  protected readonly repository = inject(TenantLoginProviderRepository);

  protected override appliesTo(items: TenantLoginProvider[]) {
    return items.every((item) => item.enabled !== false);
  }

  protected runSelection(items: TenantLoginProvider[]) {
    return this.repository.disableSelection({ uids: items.map((item) => item.uid) });
  }
}
